  for (i = 1; i < N; i++) { var pc = bars[i - 1][4], hi = Math.max(bars[i][2], pc), lo = Math.min(bars[i][3], pc), sp = hi - lo + tick(bars[i][4]); ev.push(sp > 0 ? V[i] * (bars[i][4] - pc) / sp : 0); }
