  for (k = 0; k < urut.length; k++) tot += urut[k];
  for (k = 0; k < urut.length; k++) { akum += urut[k]; if (akum >= tot / 2) { sep = urut[k]; break; } }
  var dari = Math.floor(N * 2 / 3), lp = 0, hargaAwal = bars[dari][4], hargaAkhir = bars[N - 1][4];
